arguments.command:
python -c "
import py_compile, sys, glob

files = glob.glob('harness/**/*.py', recursive=True)
errors = []
for f in sorted(files):
    try:
        py_compile.compile(f, doraise=True)
    except py_compile.PyCompileError as e:
        errors.append(str(e))

if errors:
    for e in errors:
        print(e, file=sys.stderr)
    sys.exit(1)
else:
    print(f'All {len(files)} files parse OK.')
"
